function sort_elemento(elemento,descricao){
  elemento.sort(function(a, b) {	  
  var descricaoA = a[descricao].toLowerCase(),
    descricaoB = b[descricao].toLowerCase();
  if (descricaoA < descricaoB) return -1;
  if (descricaoA > descricaoB) return 1;
  return 0;
});
}
